import { expect, test } from '@playwright/test';
import { gotoHydrated } from './support/hydrated';

/**
 * `<sui-checkbox>` renders with `shadow: 'open'` (Checkbox.wc.svelte). Checkbox.svelte
 * restores the native `change`/`input` events that the role="checkbox" box's synthetic
 * click suppresses (see form-association.test.ts), and dispatches them with
 * `composed: true` so they reach a light-DOM ancestor such as a consumer's own <form>.
 * `src/lib/Checkbox/Checkbox.composed-event.test.ts` covers that against the component
 * mounted into a real open shadow root; these two tests exercise the actual
 * `<sui-checkbox>` custom element from the built `dist-wc` bundle, the same vantage
 * point a consumer has.
 */
const loadCheckboxTag = async (page: import('@playwright/test').Page): Promise<void> => {
  await gotoHydrated(page, '/');
  await page.addScriptTag({ path: 'dist-wc/index.js', type: 'module' });
  await page.waitForFunction(() => Boolean(customElements.get('sui-checkbox')));
};

test.describe('sui-checkbox — change event crosses the shadow boundary', () => {
  test('a light-DOM form outside the shadow root observes the change event', async ({ page }) => {
    await loadCheckboxTag(page);

    await page.evaluate(() => {
      const form = document.createElement('form');
      form.setAttribute('data-pw', 'wc-checkbox-form');

      const checkbox = document.createElement('sui-checkbox');
      checkbox.setAttribute('data-pw', 'wc-checkbox');
      checkbox.setAttribute('name', 'agree');
      checkbox.setAttribute('text', 'Agree to terms');
      form.append(checkbox);
      document.body.append(form);

      const win = window as Window & { __formChangeCount?: number };
      win.__formChangeCount = 0;
      // Attached on the FORM, in the light DOM, well outside sui-checkbox's shadow
      // root -- exactly the listener a consumer wiring up their own <form> would add.
      form.addEventListener('change', () => {
        win.__formChangeCount = (win.__formChangeCount ?? 0) + 1;
      });
    });

    await page.getByTestId('wc-checkbox').locator('label.container').click();

    const box = page.getByTestId('wc-checkbox').locator('[role="checkbox"]');
    await expect(box).toHaveAttribute('aria-checked', 'true');

    await expect
      .poll(() =>
        page.evaluate(() => (window as Window & { __formChangeCount?: number }).__formChangeCount)
      )
      .toBe(1);
  });

  test('the native input itself also observes a composed input event', async ({ page }) => {
    await loadCheckboxTag(page);

    await page.evaluate(() => {
      const checkbox = document.createElement('sui-checkbox');
      checkbox.setAttribute('data-pw', 'wc-checkbox-input-event');
      checkbox.setAttribute('name', 'agree');
      document.body.append(checkbox);
    });

    // Listen from OUTSIDE the shadow root (document), the same vantage point a
    // consumer's own global listener or a form library's delegated handler uses.
    const composed = await page.evaluate(async () => {
      const host = document.querySelector('sui-checkbox[data-pw="wc-checkbox-input-event"]');
      const label = host?.shadowRoot?.querySelector('label.container');
      if (!(label instanceof HTMLElement)) {
        return 'label not found';
      }
      const seen: string[] = [];
      document.addEventListener('input', (event) => seen.push(String(event.composed)));
      label.click();
      await new Promise((resolve) => setTimeout(resolve, 50));
      return seen.join(',');
    });

    expect(composed).toBe('true');
  });
});

import { expect, test } from '@playwright/test';
import { gotoHydrated } from './support/hydrated';

test.describe('ChatComposer — async onsubmit and independent per-control disable', () => {
  // #526: an onsubmit resolving to `false` must leave the draft (value +
  // attachments) exactly as it was, instead of the unconditional clear the
  // composer applied before. This drives the actual component through its
  // real async path (a genuine setTimeout-based promise on the demo page),
  // not just the extracted `shouldApplyClear` unit under test elsewhere.
  test('a failed async send keeps the typed draft; a successful one clears it', async ({
    page
  }) => {
    await gotoHydrated(page, '/components/chat-composer');

    const input = page.getByTestId('async-submit-input');
    const send = page.getByTestId('async-submit-send');
    const failToggle = page.getByTestId('async-submit-fail-toggle');

    // Failure path: the draft must survive the resolved `false`.
    await failToggle.check();
    await input.fill('this send will fail');
    await send.click();
    await expect(page.getByTestId('async-submit-sent')).toHaveCount(0);
    // `sendDisabled` is bound to the pending flag, so the send button only
    // re-enables once the 300ms fakeSend actually settles — waiting on it
    // here is what makes the value check below prove the clear was
    // genuinely skipped, rather than merely not-yet-applied because the
    // promise hadn't resolved yet.
    await expect(send).toBeEnabled();
    await expect(input).toHaveValue('this send will fail');

    // Success path: the same input, unblocked, clears as normal.
    await failToggle.uncheck();
    await send.click();
    await expect(page.getByTestId('async-submit-sent')).toHaveText('this send will fail');
    await expect(input).toHaveValue('');
  });

  // #526: a rejected `onsubmit` promise must keep the draft exactly like a
  // resolved `false` does — ChatComposer.svelte catches the rejection and
  // never calls the clearing logic (see submitResult.ts). This drives the
  // real rejection path (an actual thrown error inside the demo's fakeSend),
  // not just the resolved-`false` branch the previous test covers.
  test('a rejected async send keeps the typed draft, same as a resolved false', async ({
    page
  }) => {
    await gotoHydrated(page, '/components/chat-composer');

    const input = page.getByTestId('async-submit-input');
    const send = page.getByTestId('async-submit-send');
    const rejectToggle = page.getByTestId('async-submit-reject-toggle');

    await rejectToggle.check();
    await input.fill('this send will reject');
    await send.click();
    await expect(page.getByTestId('async-submit-sent')).toHaveCount(0);
    // Wait for the 300ms fakeSend (and its rejection) to actually settle
    // before asserting the draft — same reasoning as the failure-path test.
    await expect(send).toBeEnabled();
    await expect(input).toHaveValue('this send will reject');
  });

  // #526: sendDisabled must gate only the send button — the textarea and any
  // other control stay interactive. Proven here by typing into the input
  // while a send is in flight (sendDisabled is bound to the pending flag).
  test('sendDisabled bound to a pending flag blocks only the send button', async ({ page }) => {
    await gotoHydrated(page, '/components/chat-composer');

    const input = page.getByTestId('async-submit-input');
    const send = page.getByTestId('async-submit-send');

    await input.fill('checking the pending gate');
    await send.click();
    await expect(send).toBeDisabled();
    // The textarea keeps taking input while the send is in flight.
    await input.fill('checking the pending gate, still typing');
    await expect(input).toBeEnabled();
    await expect(send).toBeEnabled();
  });

  // #526: textDisabled / voiceDisabled each gate one control independently,
  // with the other control (and the shared `disabled` prop, left `false`
  // throughout this demo) left untouched.
  test('textDisabled and voiceDisabled each gate only their own control', async ({ page }) => {
    await gotoHydrated(page, '/components/chat-composer');

    const input = page.getByTestId('per-control-disable-input');
    const voice = page.getByTestId('per-control-disable-voice');
    const textToggle = page.getByTestId('per-control-disable-text-toggle');
    const voiceToggle = page.getByTestId('per-control-disable-voice-toggle');

    await expect(input).toBeEnabled();
    await expect(voice).toBeEnabled();

    // Disable the textarea only: voice stays clickable.
    await textToggle.check();
    await expect(input).toBeDisabled();
    await expect(voice).toBeEnabled();
    await voice.click();
    await expect(page.getByTestId('per-control-disable-voice-count')).toHaveText(
      'Voice activations: 1'
    );

    // Re-enable the textarea, disable voice instead: textarea stays usable.
    await textToggle.uncheck();
    await voiceToggle.check();
    await expect(input).toBeEnabled();
    await expect(voice).toBeDisabled();
    await input.fill('voice is off, typing still works');
    await expect(input).toHaveValue('voice is off, typing still works');
  });
});

// Registers a beforeEach/afterEach pair around every test that unmounts
// whatever a previous case rendered and waits for Svelte to flush -- without
// it, a second render() in the same file finds the previous test's markup
// still in `document.body` and every query that expects one match finds two.
import '@testing-library/svelte/vitest';

import { expect, test } from '@playwright/test';
import { gotoHydrated } from './support/hydrated';

// The use:tooltip action used to centre its bubble on the trigger with a bare
// translate(-50%) and no edge handling: a trigger near the viewport edge
// spilled its bubble off-screen, and a trigger near the bottom pushed the
// bubble out of view. The bubble now clamps to the viewport (8px margin),
// flips to the opposite side when the preferred side lacks room, and keeps
// its arrow anchored over the trigger.
test.describe('tooltip action — viewport clamping', () => {
  test('left-edge trigger keeps its bubble inside the viewport with the arrow on the trigger', async ({
    page
  }) => {
    await gotoHydrated(page, '/components/tooltip');

    const trigger = page.getByTestId('tooltip-edge-left');
    // Pin the trigger to the exact viewport edge so the test is independent of
    // the demo page's own gutters.
    await trigger.evaluate((el) => {
      el.style.position = 'fixed';
      el.style.left = '4px';
      el.style.top = '300px';
    });
    await trigger.hover();
    const bubble = page.locator('[role="tooltip"]');
    await expect(bubble).toBeVisible();

    const bubbleBox = await bubble.boundingBox();
    const triggerBox = await trigger.boundingBox();
    if (bubbleBox === null || triggerBox === null) {
      throw new Error('boundingBox is null');
    }
    expect(bubbleBox.x).toBeGreaterThanOrEqual(0);

    // The arrow (first child div) must still point at the trigger.
    const arrowBox = await bubble.locator('div').first().boundingBox();
    if (arrowBox === null) {
      throw new Error('arrow boundingBox is null');
    }
    const arrowCenter = arrowBox.x + arrowBox.width / 2;
    expect(arrowCenter).toBeGreaterThanOrEqual(triggerBox.x - 1);
    expect(arrowCenter).toBeLessThanOrEqual(triggerBox.x + triggerBox.width + 1);
  });

  test('right-edge trigger keeps its bubble inside the viewport', async ({ page }) => {
    await gotoHydrated(page, '/components/tooltip');

    const trigger = page.getByTestId('tooltip-edge-right');
    await trigger.evaluate((el) => {
      el.style.position = 'fixed';
      el.style.left = 'auto';
      el.style.right = '4px';
      el.style.top = '300px';
    });
    await trigger.hover();
    const bubble = page.locator('[role="tooltip"]');
    await expect(bubble).toBeVisible();

    const bubbleBox = await bubble.boundingBox();
    const viewport = page.viewportSize();
    if (bubbleBox === null || viewport === null) {
      throw new Error('boundingBox or viewport is null');
    }
    expect(Math.round(bubbleBox.x + bubbleBox.width)).toBeLessThanOrEqual(viewport.width);
    // The old code shrank-to-fit against the viewport's right edge instead of
    // shifting left — a degenerate ~60px-wide, 200px-tall text column. The
    // clamped bubble keeps its natural max-width shape.
    expect(bubbleBox.width).toBeGreaterThan(150);
    expect(bubbleBox.height).toBeLessThan(120);
  });

  test('bottom-positioned tooltip flips above a trigger sitting at the viewport bottom', async ({
    page
  }) => {
    await gotoHydrated(page, '/components/tooltip');

    const trigger = page.getByTestId('tooltip-edge-left');
    // Scroll so the trigger sits ~30px above the viewport bottom — no room below.
    await trigger.evaluate((el) => {
      const rect = el.getBoundingClientRect();
      window.scrollBy(0, rect.bottom - window.innerHeight + 30);
    });
    await trigger.hover();
    const bubble = page.locator('[role="tooltip"]');
    await expect(bubble).toBeVisible();

    const bubbleBox = await bubble.boundingBox();
    const triggerBox = await trigger.boundingBox();
    if (bubbleBox === null || triggerBox === null) {
      throw new Error('boundingBox is null');
    }
    // Flipped: the bubble sits fully above the trigger instead of below it.
    expect(bubbleBox.y + bubbleBox.height).toBeLessThanOrEqual(triggerBox.y + 1);
  });
});

import { expect, test, type Page } from '@playwright/test';
import { gotoHydrated } from './support/hydrated';

// Closes #528: HITL supported exactly one decision (confirm/cancel), so a
// third disposition (e.g. "deny with instructions") or any free-text/
// multi-select control had nowhere to live and consumers hand-rolled a
// separate Card instead of using HITL at all. `actions` adds extra buttons
// that never settle the card; `children` adds an extra content slot rendered
// only while the card is pending. Both are additive and off by default.
test.describe('HITL — extra actions and children (#528)', () => {
  test('an extra action never settles the card and calls its own onSelect', async ({ page }) => {
    await gotoHydrated(page, '/components/hitl');

    const card = page.getByTestId('demo-extra');
    await expect(card).toBeVisible();

    const extra = page.getByTestId('demo-extra-action-0');
    await expect(extra).toHaveText('Deny with instructions…');

    await extra.click();

    // Selecting it ran the consumer's onSelect (the counter incremented and the
    // children snippet's textarea appeared) ...
    await expect(page.getByTestId('demo-extra-count')).toHaveText('1');
    await expect(page.getByTestId('demo-extra-note')).toBeVisible();

    // ... but the card itself is NOT settled: no completion strip, and
    // confirm/cancel are both still there and still clickable.
    await expect(page.getByTestId('demo-extra-completion')).toHaveCount(0);
    await expect(page.getByTestId('demo-extra-confirm')).toBeVisible();
    await expect(page.getByTestId('demo-extra-cancel')).toBeVisible();
  });

  test('confirm still settles the card normally with an extra action present', async ({ page }) => {
    await gotoHydrated(page, '/components/hitl');

    await page.getByTestId('demo-extra-confirm').click();

    await expect(page.getByTestId('demo-extra-completion')).toBeVisible();
    await expect(page.getByTestId('demo-extra-completion-text')).toHaveText('Approved');
    // Settled: the extra action button is gone along with cancel/confirm.
    await expect(page.getByTestId('demo-extra-action-0')).toHaveCount(0);
  });

  test('default HITL usage (no actions, no children) renders unchanged: exactly two buttons', async ({
    page
  }) => {
    await gotoHydrated(page, '/components/hitl');

    const card = page.getByTestId('demo-confirmation');
    await expect(card).toBeVisible();
    await expect(card.locator('.action-buttons > div')).toHaveCount(2);
    await expect(card.locator('.extra-content')).toHaveCount(0);
  });

  // Passing `children` with no `sections`/`functionArguments` must not, by
  // itself, suppress the "No parameters" placeholder -- only `questions`
  // does that. `demo-extra` is exactly this shape (an extra action plus a
  // conditionally-rendered children textarea, no sections/args/questions).
  test('a card with only children (no sections/functionArguments/questions) still shows "No parameters"', async ({
    page
  }) => {
    await gotoHydrated(page, '/components/hitl');

    const card = page.getByTestId('demo-extra');
    await expect(card.locator('.parameter-label')).toHaveText('PARAMETERS');
    await expect(card.locator('.parameter-value')).toHaveText('No parameters');
  });
});

// The action row used to be a non-wrapping flex line inside a `contain: layout` card.
// With a third button it was wider than a phone: Confirm sat past the screen edge
// reading "Confi", outside its card, and because layout containment keeps overflow out
// of the document's scrollable width there was nothing to scroll to. The row now
// breaks between buttons when they do not fit.
test.describe('HITL — action row on a narrow card', () => {
  const boxOf = async (page: Page, testId: string) => {
    const box = await page.getByTestId(testId).boundingBox();
    expect(box, `${testId} is laid out`).not.toBeNull();
    return box as NonNullable<typeof box>;
  };

  for (const width of [390, 320]) {
    test(`all three buttons stay inside the card and the screen at ${width}px`, async ({
      page
    }) => {
      await page.setViewportSize({ width, height: 844 });
      await gotoHydrated(page, '/components/hitl');

      const card = await boxOf(page, 'demo-extra');
      for (const id of ['demo-extra-cancel', 'demo-extra-action-0', 'demo-extra-confirm']) {
        const box = await boxOf(page, id);
        expect(box.x, `${id} starts inside the card`).toBeGreaterThanOrEqual(card.x - 0.5);
        expect(box.x + box.width, `${id} ends inside the card`).toBeLessThanOrEqual(
          card.x + card.width + 0.5
        );
        expect(box.x + box.width, `${id} ends inside the screen`).toBeLessThanOrEqual(width);
      }
      // It wrapped rather than shrinking text: one of the buttons is on a lower line.
      const tops = await Promise.all(
        ['demo-extra-cancel', 'demo-extra-action-0', 'demo-extra-confirm'].map(
          async (id) => (await boxOf(page, id)).y
        )
      );
      expect(new Set(tops.map(Math.round)).size).toBeGreaterThan(1);

      // Reachable, not merely drawn: a click lands on the real Confirm.
      await page.getByTestId('demo-extra-confirm').click();
      await expect(page.getByTestId('demo-extra-completion-text')).toHaveText('Approved');
    });

    test(`a two-button card keeps both on one line at ${width}px`, async ({ page }) => {
      await page.setViewportSize({ width, height: 844 });
      await gotoHydrated(page, '/components/hitl');
      // The "manual only" card has no timers, so its buttons are always there.
      const cancel = await page.getByRole('button', { name: 'Not yet' }).boundingBox();
      const confirm = await page.getByRole('button', { name: 'Publish now' }).boundingBox();
      expect(cancel).not.toBeNull();
      expect(confirm).not.toBeNull();
      expect(Math.abs((cancel?.y ?? 0) - (confirm?.y ?? 99))).toBeLessThan(1);
      expect(confirm?.x ?? 0).toBeGreaterThan((cancel?.x ?? 0) + (cancel?.width ?? 0) - 1);
    });
  }

  test('on a wide column the three buttons share one line, as before', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    await gotoHydrated(page, '/components/hitl');
    const tops = await Promise.all(
      ['demo-extra-cancel', 'demo-extra-action-0', 'demo-extra-confirm'].map(
        async (id) => (await boxOf(page, id)).y
      )
    );
    expect(new Set(tops.map(Math.round)).size).toBe(1);
  });
});

import { readFileSync } from 'node:fs';
import { expect, test } from '@playwright/test';
import type { Page } from '@playwright/test';
import { gotoHydrated } from './support/hydrated';

// Gallery's edit and delete actions sit inside .gallery-item-actions-frame, a container for the
// narrow-tile rule. A consumer's editIcon snippet renders inside that frame, so the frame must not
// change where the snippet's own positioned content lands. Measured before this test existed
// (Chromium, Firefox, WebKit): inline-size containment does not make the frame the containing block
// of a position:fixed child, and a fixed child is still contained by the action's default
// backdrop-filter exactly as it was before the frame was added. These tests fail if that changes.

type WcModule = {
  createRawSnippet?: (factory: () => { render: () => string }) => unknown;
};

type Offsets = {
  readonly fixedFromButton: { readonly dx: number; readonly dy: number };
  readonly absoluteFromButton: { readonly dx: number; readonly dy: number };
  readonly fixedInViewport: { readonly x: number; readonly y: number };
};

const mountGalleryWithIconSnippet = async (
  page: Page,
  width: number,
  backdropFilter: string | null
): Promise<Offsets> => {
  await page.setViewportSize({ width, height: 900 });
  await gotoHydrated(page, '/');
  await page.route('**/__sui-wc.js', (route) =>
    route.fulfill({
      status: 200,
      contentType: 'application/javascript',
      body: readFileSync('dist-wc/index.js', 'utf8')
    })
  );
  await page.addScriptTag({
    content: `import('/__sui-wc.js').then((module) => { window.__suiWcModule = module; });`,
    type: 'module'
  });
  await page.waitForFunction(
    () =>
      typeof customElements.get('sui-gallery') !== 'undefined' &&
      typeof (window as Window & { __suiWcModule?: WcModule }).__suiWcModule === 'object',
    { timeout: 15_000 }
  );

  return page.evaluate(async (filter) => {
    const module = (window as Window & { __suiWcModule?: WcModule }).__suiWcModule;
    if (typeof module?.createRawSnippet !== 'function') {
      throw new Error('the WC entry must export createRawSnippet');
    }
    const gallery = document.createElement('sui-gallery');
    if (filter !== null) {
      gallery.style.setProperty('--gallery-item-action-backdrop-filter', filter);
    }
    const pixel = 'data:image/gif;base64,R0lGODlhAQABAAAAACw=';
    Reflect.set(gallery, 'images', [
      { src: pixel, alt: 'one' },
      { src: pixel, alt: 'two' },
      { src: pixel, alt: 'three' }
    ]);
    Reflect.set(gallery, 'oneditclick', () => null);
    Reflect.set(
      gallery,
      'editIcon',
      module.createRawSnippet(() => ({
        render: () =>
          '<span><i id="fixed-child" style="position:fixed;top:11px;left:13px;width:6px;height:6px"></i>' +
          '<i id="absolute-child" style="position:absolute;top:2px;left:3px;width:4px;height:4px"></i></span>'
      }))
    );
    document.body.append(gallery);
    await new Promise((resolve) => setTimeout(resolve, 300));

    const root = gallery.shadowRoot;
    const button = root?.querySelector('.gallery-item-action button');
    const fixedChild = root?.querySelector('#fixed-child');
    const absoluteChild = root?.querySelector('#absolute-child');
    if (!button || !fixedChild || !absoluteChild) {
      throw new Error('the custom edit icon did not render inside the action button');
    }
    const b = button.getBoundingClientRect();
    const f = fixedChild.getBoundingClientRect();
    const a = absoluteChild.getBoundingClientRect();
    return {
      fixedFromButton: { dx: f.x - b.x, dy: f.y - b.y },
      absoluteFromButton: { dx: a.x - b.x, dy: a.y - b.y },
      fixedInViewport: { x: f.x, y: f.y }
    };
  }, backdropFilter);
};

for (const width of [1280, 320]) {
  test(`a custom editIcon keeps its positioned children where they were at ${width}px`, async ({
    page
  }) => {
    // Default styling: the action's backdrop-filter contains the fixed child, so it sits at its
    // authored offset from the button, and the absolute child at its authored offset.
    const offsets = await mountGalleryWithIconSnippet(page, width, null);
    expect(offsets.fixedFromButton.dx).toBeCloseTo(13, 0);
    expect(offsets.fixedFromButton.dy).toBeCloseTo(11, 0);
    expect(offsets.absoluteFromButton.dx).toBeCloseTo(3, 0);
    expect(offsets.absoluteFromButton.dy).toBeCloseTo(2, 0);
  });

  test(`with the backdrop filter off, a fixed icon child still anchors to the viewport at ${width}px`, async ({
    page
  }) => {
    // Nothing else contains it now. If the frame ever became its containing block, this child would
    // land inside the tile instead of at the viewport's top-left.
    const offsets = await mountGalleryWithIconSnippet(page, width, 'none');
    expect(offsets.fixedInViewport.x).toBeCloseTo(13, 0);
    expect(offsets.fixedInViewport.y).toBeCloseTo(11, 0);
  });
}

import { expect, test } from '@playwright/test';
import type { Page } from '@playwright/test';
import { gotoHydrated } from './support/hydrated';

// A three-column grid on a 320px phone makes each tile about 79px wide, and 305px (what a desktop
// browser's 15px scrollbar leaves of 320) about 75px. Two default 36px action buttons plus their gap and
// insets need 92px, so the left button used to sit past the tile's overflow:hidden edge: its centre was
// still clickable, but a strip of the button, and its outline, was cut off. These tests read the real
// geometry and hit-test the button's own edges, not just its bounding box.

type Overhang = {
  readonly name: string;
  readonly size: number;
  readonly left: number;
  readonly right: number;
  readonly top: number;
  readonly bottom: number;
  readonly edgesReachable: boolean;
};

const measureActions = (page: Page): Promise<readonly Overhang[]> =>
  page.evaluate(() =>
    [...document.querySelectorAll('.gallery-item-actions button')].map((button) => {
      const r = button.getBoundingClientRect();
      const tile = button.closest('.gallery-item')!.getBoundingClientRect();
      const topmostIsButton = (x: number, y: number): boolean => {
        const hit = document.elementFromPoint(x, y);
        return hit !== null && button.contains(hit);
      };
      // Inset 2px so the check lands on the button's own pixels, at all four edges and the centre.
      const points: ReadonlyArray<readonly [number, number]> = [
        [r.left + 2, r.top + r.height / 2],
        [r.right - 2, r.top + r.height / 2],
        [r.left + r.width / 2, r.top + 2],
        [r.left + r.width / 2, r.bottom - 2],
        [r.left + r.width / 2, r.top + r.height / 2]
      ];
      return {
        name: button.getAttribute('aria-label') ?? '',
        size: Math.round(r.width * 10) / 10,
        left: Math.max(0, tile.left - r.left),
        right: Math.max(0, r.right - tile.right),
        top: Math.max(0, tile.top - r.top),
        bottom: Math.max(0, r.bottom - tile.bottom),
        edgesReachable: points.every(([x, y]) => topmostIsButton(x, y))
      };
    })
  );

for (const width of [390, 320, 305]) {
  test(`every item action sits fully inside its tile and is reachable at ${width}px`, async ({
    page
  }) => {
    await page.setViewportSize({ width, height: 900 });
    await gotoHydrated(page, '/components/gallery');

    const actions = await measureActions(page);
    expect(actions.length).toBeGreaterThan(0);
    for (const action of actions) {
      expect(action, action.name).toMatchObject({
        left: 0,
        right: 0,
        top: 0,
        bottom: 0,
        edgesReachable: true
      });
      // Shrunk, but still a usable target (WCAG 2.5.8 minimum is 24px).
      expect(action.size, action.name).toBeGreaterThanOrEqual(24);
    }
  });
}

test('at a roomy width the buttons keep their default 36px size', async ({ page }) => {
  await page.setViewportSize({ width: 1280, height: 900 });
  await gotoHydrated(page, '/components/gallery');

  const actions = await measureActions(page);
  expect(actions.length).toBeGreaterThan(0);
  for (const action of actions) {
    expect(action.size, action.name).toBe(36);
  }
});

test('a consumer-set size still wins when the tile is narrow', async ({ page }) => {
  await page.setViewportSize({ width: 320, height: 900 });
  await gotoHydrated(page, '/components/gallery');
  const before = await measureActions(page);

  // The narrow-tile sizes are fallbacks under the public variables, so this must make the buttons
  // bigger than the shrunk default, not be overridden by it.
  await page.addStyleTag({ content: '.gallery { --gallery-item-action-padding: 10px; }' });
  const after = await measureActions(page);

  expect(after.length).toBe(before.length);
  for (let i = 0; i < after.length; i += 1) {
    expect(after[i].size, after[i].name).toBeGreaterThan(before[i].size);
  }
});

// The narrow-tile rule is a container query on the tile, and a container with inline-size containment
// reports no intrinsic width. Inside an ancestor that sizes to its content (inline-block, fit-content, an
// auto-width absolutely positioned box) the grid then had nothing to measure and collapsed to its gaps. The
// default block layout hides this, so the check has to put the gallery in such an ancestor.
const shrinkToFitAncestors: ReadonlyArray<readonly [string, string]> = [
  ['inline-block', 'display: inline-block'],
  ['width: fit-content', 'width: fit-content'],
  ['an auto-width absolutely positioned box', 'position: absolute; left: 0; top: 0']
];

for (const [label, style] of shrinkToFitAncestors) {
  test(`a gallery inside ${label} keeps the width its tiles give it`, async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 900 });
    await gotoHydrated(page, '/components/gallery');

    const size = await page.evaluate((wrapperStyle) => {
      const source = document.querySelector('main .gallery.grid');
      if (source === null) {
        throw new Error('no grid gallery on the page');
      }
      const wrapper = document.createElement('div');
      wrapper.setAttribute('style', wrapperStyle);
      wrapper.append(source.cloneNode(true));
      document.body.append(wrapper);
      const gallery = wrapper.querySelector('.gallery');
      const tile = wrapper.querySelector('.gallery-item');
      if (gallery === null || tile === null) {
        throw new Error('clone lost its gallery');
      }
      return {
        gallery: gallery.getBoundingClientRect().width,
        tile: tile.getBoundingClientRect().width
      };
    }, style);

    // Before the narrow-tile rule these were 880px and 288px; a collapsed grid is 16px and 0px.
    expect(size.tile).toBeGreaterThan(100);
    expect(size.gallery).toBeGreaterThan(size.tile * 2);
  });
}

