import { afterEach, describe, expect, it, vi } from 'vitest';
import { dismissibleLayerCount, registerDismissible } from './dismissal';

const press = (
  key: string,
  init: KeyboardEventInit = {},
  target: EventTarget = document
): boolean =>
  target.dispatchEvent(
    new KeyboardEvent('keydown', { key, bubbles: true, cancelable: true, composed: true, ...init })
  );

function layerElement(): HTMLElement {
  const element = document.createElement('div');
  document.body.append(element);
  return element;
}

afterEach(() => {
  document.body.replaceChildren();
});

describe('dismissal stack ownership', () => {
  it('sends Escape to the most recently registered layer only', () => {
    const outer = vi.fn();
    const inner = vi.fn();
    const releaseOuter = registerDismissible({ element: () => layerElement(), onEscape: outer });
    const releaseInner = registerDismissible({ element: () => layerElement(), onEscape: inner });

    press('Escape');

    expect(inner).toHaveBeenCalledTimes(1);
    expect(outer).not.toHaveBeenCalled();

    releaseInner();
    press('Escape');
    expect(outer).toHaveBeenCalledTimes(1);
    expect(inner).toHaveBeenCalledTimes(1);

    releaseOuter();
  });

  it('ignores keys other than Escape', () => {
    const onEscape = vi.fn();
    const release = registerDismissible({ element: () => layerElement(), onEscape });

    press('Enter');
    press('a');

    expect(onEscape).not.toHaveBeenCalled();
    release();
  });

  it('does not dismiss for composing Escape from a shadow-root input', () => {
    const outer = vi.fn();
    const inner = vi.fn();
    const releaseOuter = registerDismissible({ element: () => layerElement(), onEscape: outer });
    const releaseInner = registerDismissible({ element: () => layerElement(), onEscape: inner });
    const host = document.createElement('div');
    const input = document.createElement('input');
    host.attachShadow({ mode: 'open' }).append(input);
    document.body.append(host);

    press('Escape', { isComposing: true }, input);
    press('Escape', { keyCode: 229 }, input);

    expect(inner).not.toHaveBeenCalled();
    expect(outer).not.toHaveBeenCalled();

    press('Escape', {}, input);

    expect(inner).toHaveBeenCalledTimes(1);
    expect(outer).not.toHaveBeenCalled();
    releaseInner();
    releaseOuter();
  });

  it('treats a press inside the topmost layer as inside, and outside as outside', () => {
    const element = layerElement();
    const child = document.createElement('button');
    element.append(child);
    const onOutside = vi.fn();
    const release = registerDismissible({ element: () => element, onOutside });

    child.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, composed: true }));
    expect(onOutside).not.toHaveBeenCalled();

    document.body.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, composed: true }));
    expect(onOutside).toHaveBeenCalledTimes(1);

    release();
  });

  it('does not tell a covered layer about a press, even outside its own element', () => {
    const under = layerElement();
    const over = layerElement();
    const underOutside = vi.fn();
    const overOutside = vi.fn();
    const releaseUnder = registerDismissible({ element: () => under, onOutside: underOutside });
    const releaseOver = registerDismissible({ element: () => over, onOutside: overOutside });

    document.body.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, composed: true }));

    expect(overOutside).toHaveBeenCalledTimes(1);
    expect(underOutside).not.toHaveBeenCalled();

    releaseOver();
    releaseUnder();
  });

  it('releases a layer from the middle of the stack without disturbing the rest', () => {
    const first = vi.fn();
    const second = vi.fn();
    const third = vi.fn();
    const releaseFirst = registerDismissible({ element: () => layerElement(), onEscape: first });
    const releaseSecond = registerDismissible({ element: () => layerElement(), onEscape: second });
    const releaseThird = registerDismissible({ element: () => layerElement(), onEscape: third });

    releaseSecond();
    press('Escape');
    expect(third).toHaveBeenCalledTimes(1);

    releaseThird();
    press('Escape');
    expect(first).toHaveBeenCalledTimes(1);
    expect(second).not.toHaveBeenCalled();

    releaseFirst();
  });

  it('detaches its listeners once the last layer is released', () => {
    expect(dismissibleLayerCount()).toBe(0);
    const onEscape = vi.fn();
    const release = registerDismissible({ element: () => layerElement(), onEscape });
    expect(dismissibleLayerCount()).toBe(1);

    release();
    expect(dismissibleLayerCount()).toBe(0);

    press('Escape');
    expect(onEscape).toHaveBeenCalledTimes(0);

    // Releasing twice must not corrupt the stack.
    release();
    expect(dismissibleLayerCount()).toBe(0);
  });

  it('skips a layer whose element has gone, rather than trapping dismissal', () => {
    const onOutside = vi.fn();
    const release = registerDismissible({ element: () => null, onOutside });

    document.body.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, composed: true }));

    expect(onOutside).toHaveBeenCalledTimes(1);
    release();
  });
});

/**
 * Unit tests for the shared focus-trap module (src/lib/_interaction/focus.ts).
 * Migrated from Modal/focus-trap.test.ts once Modal, Sheet and
 * DateRangePicker's independent copies of this logic were consolidated here
 * -- see focus.ts's module docblock for the full history.
 *
 * Pure logic, no Svelte runtime and no real DOM -- a minimal stub satisfying
 * only the `querySelectorAll(selector).item(i)` / `.length` shape the module
 * actually calls, same approach as tooltip-action.test.ts. The gap-fix cases
 * below (hidden/aria-disabled/inert) additionally stub `hasAttribute` /
 * `getAttribute` / `closest` -- the exact three methods `canReceiveFocus`
 * reads -- rather than switching this file to jsdom, so it keeps testing the
 * same pure, mount-free logic the rest of the suite does.
 *
 * @vitest-environment node
 */
import { describe, expect, it, vi } from 'vitest';
import { focusEntryPoint, focusTrapTabTarget, getFocusTrapBoundary } from './focus';

type StubFocusable = {
  focus: () => void;
  hasAttribute?: (name: string) => boolean;
  getAttribute?: (name: string) => string | null;
  closest?: (selector: string) => StubFocusable | null;
};

/** A bare candidate with no DOM methods beyond focus() -- the exact shape
 * Modal's original test suite used, kept to prove the gap-fix's duck-typed
 * guard still treats these as ordinary focusable candidates. */
function makeFocusable(): StubFocusable {
  return { focus: vi.fn() };
}

/** A candidate shaped like a real element for the three gap checks: none of
 * them trigger exclusion, unless overridden. */
function makeRealisticCandidate(overrides: Partial<StubFocusable> = {}): StubFocusable {
  return {
    focus: vi.fn(),
    hasAttribute: () => false,
    getAttribute: () => null,
    closest: () => null,
    ...overrides
  };
}

function makeHiddenCandidate(): StubFocusable {
  return makeRealisticCandidate({ hasAttribute: (name) => name === 'hidden' });
}

function makeAriaDisabledCandidate(): StubFocusable {
  return makeRealisticCandidate({
    getAttribute: (name) => (name === 'aria-disabled' ? 'true' : null)
  });
}

function makeInertDescendantCandidate(): StubFocusable {
  const inertAncestor = makeRealisticCandidate();
  return makeRealisticCandidate({
    closest: (selector) => (selector === '[inert]' ? inertAncestor : null)
  });
}

/** A container stub whose querySelectorAll always returns the given elements. */
function makeContainer(elements: readonly StubFocusable[]): ParentNode {
  const list = {
    item: (index: number) => elements[index] ?? null,
    length: elements.length
  };
  return { querySelectorAll: () => list } as unknown as ParentNode;
}

describe('getFocusTrapBoundary', () => {
  it('returns null/null for a null container', () => {
    expect(getFocusTrapBoundary(null)).toEqual({ first: null, last: null });
  });

  it('returns null/null when nothing inside is focusable', () => {
    expect(getFocusTrapBoundary(makeContainer([]))).toEqual({ first: null, last: null });
  });

  it('returns the same element as both first and last when there is exactly one', () => {
    const only = makeFocusable();
    const boundary = getFocusTrapBoundary(makeContainer([only]));
    expect(boundary.first).toBe(only);
    expect(boundary.last).toBe(only);
  });

  it('returns the first and last of several focusable descendants', () => {
    const a = makeFocusable();
    const b = makeFocusable();
    const c = makeFocusable();
    const boundary = getFocusTrapBoundary(makeContainer([a, b, c]));
    expect(boundary.first).toBe(a);
    expect(boundary.last).toBe(c);
  });

  it('skips a candidate hidden via the hidden attribute', () => {
    const hidden = makeHiddenCandidate();
    const visible = makeRealisticCandidate();
    const boundary = getFocusTrapBoundary(makeContainer([hidden, visible]));
    expect(boundary.first).toBe(visible);
    expect(boundary.last).toBe(visible);
  });

  it('skips a candidate carrying aria-disabled="true"', () => {
    const disabled = makeAriaDisabledCandidate();
    const enabled = makeRealisticCandidate();
    const boundary = getFocusTrapBoundary(makeContainer([disabled, enabled]));
    expect(boundary.first).toBe(enabled);
    expect(boundary.last).toBe(enabled);
  });

  it('skips a candidate inside an inert subtree', () => {
    const inertDescendant = makeInertDescendantCandidate();
    const normal = makeRealisticCandidate();
    const boundary = getFocusTrapBoundary(makeContainer([inertDescendant, normal]));
    expect(boundary.first).toBe(normal);
    expect(boundary.last).toBe(normal);
  });

  it('returns null/null rather than throwing when every candidate is filtered out', () => {
    const hidden = makeHiddenCandidate();
    const disabled = makeAriaDisabledCandidate();
    const inertDescendant = makeInertDescendantCandidate();
    expect(() =>
      getFocusTrapBoundary(makeContainer([hidden, disabled, inertDescendant]))
    ).not.toThrow();
    const boundary = getFocusTrapBoundary(makeContainer([hidden, disabled, inertDescendant]));
    expect(boundary).toEqual({ first: null, last: null });
  });

  it('treats a bare stub with no DOM methods as an ordinary candidate (backward compatible)', () => {
    const bare = makeFocusable();
    const boundary = getFocusTrapBoundary(makeContainer([bare]));
    expect(boundary.first).toBe(bare);
    expect(boundary.last).toBe(bare);
  });
});

describe('focusTrapTabTarget', () => {
  it('wraps Tab from the last focusable element back to the first', () => {
    const first = makeFocusable();
    const last = makeFocusable();
    const container = makeContainer([first, last]);

    const target = focusTrapTabTarget({
      container,
      activeElement: last as unknown as Element,
      shiftKey: false
    });

    expect(target).toBe(first);
  });

  it('wraps Shift+Tab from the first focusable element back to the last', () => {
    const first = makeFocusable();
    const last = makeFocusable();
    const container = makeContainer([first, last]);

    const target = focusTrapTabTarget({
      container,
      activeElement: first as unknown as Element,
      shiftKey: true
    });

    expect(target).toBe(last);
  });

  it('treats the last unfiltered candidate as the wrap edge, skipping a trailing hidden one', () => {
    const first = makeFocusable();
    const middle = makeFocusable();
    const trailingHidden = makeHiddenCandidate();
    const container = makeContainer([first, middle, trailingHidden]);

    const target = focusTrapTabTarget({
      container,
      activeElement: middle as unknown as Element,
      shiftKey: false
    });

    expect(target).toBe(first);
  });

  it('leaves the browser default alone when focus is not at an edge', () => {
    const first = makeFocusable();
    const middle = makeFocusable();
    const last = makeFocusable();
    const container = makeContainer([first, middle, last]);

    const target = focusTrapTabTarget({
      container,
      activeElement: middle as unknown as Element,
      shiftKey: false
    });

    expect(target).toBeNull();
  });

  it('does nothing when there is nothing focusable to trap between', () => {
    const target = focusTrapTabTarget({
      container: makeContainer([]),
      activeElement: null,
      shiftKey: false
    });

    expect(target).toBeNull();
  });
});

describe('focusEntryPoint', () => {
  it('focuses the first focusable descendant when there is one', () => {
    const first = makeFocusable();
    const second = makeFocusable();
    const container = makeContainer([first, second]);

    focusEntryPoint(container as unknown as HTMLElement);

    expect(first.focus).toHaveBeenCalledTimes(1);
    expect(second.focus).not.toHaveBeenCalled();
  });

  it('falls back to focusing the container itself when nothing inside is focusable', () => {
    const container = makeContainer([]);
    const focusSpy = vi.fn();
    const containerWithFocus = Object.assign(container, { focus: focusSpy });

    focusEntryPoint(containerWithFocus as unknown as HTMLElement);

    expect(focusSpy).toHaveBeenCalledTimes(1);
  });

  it('is a no-op for a null container', () => {
    expect(() => focusEntryPoint(null)).not.toThrow();
  });

  it('skips a hidden first candidate and focuses the next real one', () => {
    const hiddenFirst = makeHiddenCandidate();
    const realSecond = makeRealisticCandidate();
    const container = makeContainer([hiddenFirst, realSecond]);

    focusEntryPoint(container as unknown as HTMLElement);

    expect(hiddenFirst.focus).not.toHaveBeenCalled();
    expect(realSecond.focus).toHaveBeenCalledTimes(1);
  });
});

/**
 * Unit tests for the slot- and shadow-aware interactive-element search
 * (src/lib/_interaction/focusable.ts). jsdom provides shadow roots and
 * `HTMLSlotElement.assignedElements`, but no layout, so these cover the tree
 * walk and the attribute rules; real Tab reachability is the browser specs'
 * job (tests/scroller-keyboard-access.test.ts, tests/wc-*-.spec.ts).
 */
import { afterEach, describe, expect, it } from 'vitest';
import {
  contentElements,
  findInteractive,
  hasTabbableContent,
  interactiveElements
} from './focusable';

const mount = (html: string): HTMLElement => {
  const root = document.createElement('div');
  root.innerHTML = html;
  document.body.append(root);
  return root;
};

afterEach(() => {
  document.body.replaceChildren();
});

describe('findInteractive', () => {
  it('returns the first native control in tree order', () => {
    const root = mount(
      '<span>text</span><div><a href="/x" id="link">a</a><button id="b">b</button></div>'
    );
    expect(findInteractive(root)?.id).toBe('link');
  });

  it('skips a disabled button, a hidden input and an anchor with no href', () => {
    const root = mount(
      '<button disabled></button><input type="hidden"><a>no href</a><button id="ok"></button>'
    );
    expect(findInteractive(root)?.id).toBe('ok');
  });

  it('keeps a native control with tabindex="-1" unless only tabbable ones are wanted', () => {
    const root = mount('<button id="programmatic" tabindex="-1"></button>');
    expect(findInteractive(root)?.id).toBe('programmatic');
    expect(findInteractive(root, { tabbableOnly: true })).toBeNull();
  });

  it('counts a bare tabindex element only when it is not negative', () => {
    expect(findInteractive(mount('<div tabindex="-1"></div>'))).toBeNull();
    expect(findInteractive(mount('<div id="stop" tabindex="0"></div>'))?.id).toBe('stop');
  });

  it('ignores elements that are hidden or inside an inert subtree', () => {
    expect(findInteractive(mount('<button hidden></button>'))).toBeNull();
    expect(findInteractive(mount('<div inert><button></button></div>'))).toBeNull();
  });

  it('tests the root itself only when asked to', () => {
    const root = mount('<button id="self"></button>').firstElementChild;
    if (root === null) {
      throw new Error('fixture failed to mount');
    }
    expect(findInteractive(root)).toBeNull();
    expect(findInteractive(root, { includeRoot: true })?.id).toBe('self');
  });

  it('follows a slot to the light-DOM element assigned to it', () => {
    const host = mount(
      '<div id="host"><button slot="trigger" id="slotted">Open</button></div>'
    ).firstElementChild;
    if (host === null) {
      throw new Error('fixture failed to mount');
    }
    const shadow = host.attachShadow({ mode: 'open' });
    shadow.innerHTML = '<div id="wrapper"><slot name="trigger"></slot></div>';

    const wrapper = shadow.getElementById('wrapper');
    if (wrapper === null) {
      throw new Error('shadow fixture failed to mount');
    }
    // A plain querySelector rooted in the shadow tree cannot see the slotted button.
    expect(wrapper.querySelector('button')).toBeNull();
    expect(findInteractive(wrapper)?.id).toBe('slotted');
  });

  it("uses an unassigned slot's own fallback content", () => {
    const host = mount('<div id="host"></div>').firstElementChild;
    if (host === null) {
      throw new Error('fixture failed to mount');
    }
    const shadow = host.attachShadow({ mode: 'open' });
    shadow.innerHTML = '<div id="wrapper"><slot><button id="fallback"></button></slot></div>';
    const wrapper = shadow.getElementById('wrapper');
    if (wrapper === null) {
      throw new Error('shadow fixture failed to mount');
    }
    expect(findInteractive(wrapper)?.id).toBe('fallback');
  });

  it('descends into an open shadow root of a nested element', () => {
    const root = mount('<div><x-nested id="nested"></x-nested></div>');
    const nested = root.querySelector('#nested');
    if (nested === null) {
      throw new Error('fixture failed to mount');
    }
    nested.attachShadow({ mode: 'open' }).innerHTML = '<button id="deep"></button>';
    expect(root.querySelector('button')).toBeNull();
    expect(findInteractive(root)?.id).toBe('deep');
  });

  it("finds the control in the root's own shadow tree when the root is a host", () => {
    // The shape of `<sui-button slot="trigger">`: the host is not a control, the native
    // button it renders is, and it lives in the host's shadow root rather than beneath it.
    const host = mount('<x-button id="host"></x-button>').firstElementChild;
    if (host === null) {
      throw new Error('fixture failed to mount');
    }
    host.attachShadow({ mode: 'open' }).innerHTML = '<button id="rendered">Open</button>';

    expect(host.querySelector('button')).toBeNull();
    expect(findInteractive(host)?.id).toBe('rendered');
    expect(findInteractive(host, { includeRoot: true })?.id).toBe('rendered');
    expect(findInteractive(host, { tabbableOnly: true })?.id).toBe('rendered');
  });

  it('prefers a host that is itself a control over the one it renders', () => {
    const host = mount('<x-button id="host" tabindex="0"></x-button>').firstElementChild;
    if (host === null) {
      throw new Error('fixture failed to mount');
    }
    host.attachShadow({ mode: 'open' }).innerHTML = '<button id="rendered"></button>';
    expect(findInteractive(host, { includeRoot: true })?.id).toBe('host');
  });

  it('excludes a shadow control while its host is inert and finds it again when enabled', () => {
    const host = mount('<x-button inert></x-button>').firstElementChild;
    if (host === null) {
      throw new Error('fixture failed to mount');
    }
    host.attachShadow({ mode: 'open' }).innerHTML = '<button>Open</button>';
    expect(hasTabbableContent(host)).toBe(false);
    host.removeAttribute('inert');
    expect(hasTabbableContent(host)).toBe(true);
  });

  it('excludes a slotted control inside an inert shadow wrapper', () => {
    const host = mount('<x-card><button slot="action">Open</button></x-card>').firstElementChild;
    if (host === null) {
      throw new Error('fixture failed to mount');
    }
    const shadow = host.attachShadow({ mode: 'open' });
    shadow.innerHTML = '<div inert><slot name="action"></slot></div>';
    expect(hasTabbableContent(host)).toBe(false);
    shadow.querySelector('div')?.removeAttribute('inert');
    expect(hasTabbableContent(host)).toBe(true);
  });

  it('walks a host through its shadow tree, so slotted light children are found once, in render order', () => {
    // `first` is slotted after a button the shadow tree renders itself; `unslotted` has no
    // slot to appear in, so it is not rendered at all and must not be offered as a control.
    const host = mount(
      '<x-card id="host"><a href="#a" slot="body" id="first">a</a><button id="unslotted" slot="nowhere"></button></x-card>'
    ).firstElementChild;
    if (host === null) {
      throw new Error('fixture failed to mount');
    }
    host.attachShadow({ mode: 'open' }).innerHTML =
      '<button id="chrome"></button><slot name="body"></slot>';

    const seen = Array.from(interactiveElements(host), (el) => el.id);
    expect(seen).toEqual(['chrome', 'first']);
  });

  it('lists hidden controls too when asked, so a caller can watch them come back', () => {
    const root = mount(
      '<button id="shown"></button><button id="gone" hidden></button><div inert><button id="frozen"></button></div>'
    );
    expect(Array.from(interactiveElements(root), (el) => el.id)).toEqual(['shown']);
    expect(Array.from(interactiveElements(root, { includeHidden: true }), (el) => el.id)).toEqual([
      'shown',
      'gone',
      'frozen'
    ]);
  });

  it('returns null for a host whose shadow tree renders nothing interactive', () => {
    const host = mount('<x-icon id="host"></x-icon>').firstElementChild;
    if (host === null) {
      throw new Error('fixture failed to mount');
    }
    host.attachShadow({ mode: 'open' }).innerHTML = '<svg></svg><span>decor</span>';
    expect(findInteractive(host, { includeRoot: true })).toBeNull();
  });

  it('honours checkVisibility where the engine provides it', () => {
    const root = mount('<button id="hidden-by-layout"></button><button id="shown"></button>');
    Object.defineProperty(HTMLElement.prototype, 'checkVisibility', {
      configurable: true,
      value(this: HTMLElement) {
        return this.id !== 'hidden-by-layout';
      }
    });
    try {
      expect(findInteractive(root)?.id).toBe('shown');
    } finally {
      Reflect.deleteProperty(HTMLElement.prototype, 'checkVisibility');
    }
  });
});

describe('hasTabbableContent', () => {
  it('is false for plain content and true once a link is added', () => {
    const root = mount('<p>Nothing to focus</p>');
    expect(hasTabbableContent(root)).toBe(false);
    root.insertAdjacentHTML('beforeend', '<a href="#x">link</a>');
    expect(hasTabbableContent(root)).toBe(true);
  });

  it('does not count the root itself', () => {
    const root = mount('<button id="only"></button>').firstElementChild;
    if (root === null) {
      throw new Error('fixture failed to mount');
    }
    expect(hasTabbableContent(root)).toBe(false);
  });
});

describe('contentElements', () => {
  it('returns direct children, with a slot replaced by what is assigned to it', () => {
    const host = mount(
      '<div id="host"><p id="a" slot="s"></p><p id="b" slot="s"></p></div>'
    ).firstElementChild;
    if (host === null) {
      throw new Error('fixture failed to mount');
    }
    const shadow = host.attachShadow({ mode: 'open' });
    shadow.innerHTML = '<div id="region"><i id="own"></i><slot name="s"></slot></div>';
    const region = shadow.getElementById('region');
    if (region === null) {
      throw new Error('shadow fixture failed to mount');
    }
    expect(contentElements(region).map((el) => el.id)).toEqual(['own', 'a', 'b']);
  });
});

import { expect, test } from '@playwright/test';
import { gotoHydrated } from './support/hydrated';

// Closes #415. The DS dropdown sheet's keyboard-accessibility guidelines put
// the search box INSIDE the open menu, reached by Tab after opening, while
// Select's `searchable` put the filter input in the trigger and focused it
// automatically. That difference is not cosmetic: with the input in the
// trigger there is no way to open the menu and keep focus on the combobox, so
// a keyboard user who wanted to arrow through the options had to type first.
test.describe('Select — in-menu search (#415)', () => {
  test.beforeEach(async ({ page }) => {
    await gotoHydrated(page, '/components/select');
  });

  const openMenu = async (page: import('@playwright/test').Page) => {
    const select = page.getByTestId('select-menu-search');
    await select.locator('.select-trigger').click();
    await expect(select.locator('.select-dropdown')).toBeVisible();
    return select;
  };

  test('renders the search box inside the menu, not the trigger', async ({ page }) => {
    const select = await openMenu(page);

    await expect(select.locator('.select-dropdown .select-menu-search')).toBeVisible();
    await expect(select.locator('.select-trigger .select-search')).toHaveCount(0);
  });

  test('leaves focus on the trigger when the menu opens', async ({ page }) => {
    // The DS contract. Auto-focusing the search box is exactly what the
    // trigger-positioned variant does, and what this one must not.
    const select = await openMenu(page);

    const searchFocused = await select
      .locator('.select-menu-search')
      .evaluate((el) => el === document.activeElement);
    expect(searchFocused).toBe(false);
  });

  test('reaches the search box with Tab after opening', async ({ page }) => {
    const select = page.getByTestId('select-menu-search');

    // Opened from the keyboard rather than by click, which is both the flow
    // the DS contract describes and the only way to be sure focus starts on
    // the trigger rather than wherever a click happened to leave it.
    await select.locator('.select-trigger').focus();
    await page.keyboard.press('Enter');
    await expect(select.locator('.select-dropdown')).toBeVisible();

    await page.keyboard.press('Tab');

    const searchFocused = await select
      .locator('.select-menu-search')
      .evaluate((el) => el === document.activeElement);
    expect(searchFocused).toBe(true);
  });

  test('filters the options as the search box is typed into', async ({ page }) => {
    const select = await openMenu(page);

    await select.locator('.select-menu-search').fill('lon');

    await expect(select.locator('.select-option')).toHaveCount(1);
    await expect(select.locator('.select-option')).toHaveText('London');
  });

  test('keeps arrow-key navigation working from the search box', async ({ page }) => {
    const select = await openMenu(page);
    const search = select.locator('.select-menu-search');

    await search.focus();
    await page.keyboard.press('ArrowDown');

    await expect(select.locator('.select-option.highlighted')).toHaveCount(1);
  });

  test('selects the highlighted option with Enter from the search box', async ({ page }) => {
    const select = await openMenu(page);
    const search = select.locator('.select-menu-search');

    await search.focus();
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('Enter');

    await expect(select.locator('.select-value')).toHaveText('New York');
  });

  test('closes on Escape from the search box', async ({ page }) => {
    const select = await openMenu(page);

    await select.locator('.select-menu-search').focus();
    await page.keyboard.press('Escape');

    await expect(select.locator('.select-dropdown')).toHaveCount(0);
  });

  test('keeps the listbox role off the panel and on the option list', async ({ page }) => {
    // A listbox may only contain options, so a search box inside one is
    // invalid. The panel therefore carries no role and the inner list owns it
    // — and aria-controls has to point at the list, not the panel.
    const select = await openMenu(page);

    await expect(select.locator('.select-dropdown')).not.toHaveAttribute('role', 'listbox');
    await expect(select.locator('.select-menu-list')).toHaveAttribute('role', 'listbox');

    const controls = await select.locator('.select-trigger').getAttribute('aria-controls');
    await expect(select.locator('.select-menu-list')).toHaveAttribute('id', String(controls));
  });

  test('the search box is not inside the listbox element', async ({ page }) => {
    const select = await openMenu(page);
    await expect(select.locator('.select-menu-list .select-menu-search')).toHaveCount(0);
  });

  test('preserves the dropdown stacking order', async ({ page }) => {
    const select = await openMenu(page);
    await expect(select.locator('.select-dropdown')).toHaveCSS('z-index', '10');
  });

  test('Shift+Tab from the search returns to the trigger without closing', async ({ page }) => {
    const select = await openMenu(page);
    await select.locator('.select-menu-search').focus();
    await page.keyboard.press('Shift+Tab');
    await expect(select.locator('.select-trigger')).toBeFocused();
    await expect(select.locator('.select-dropdown')).toBeVisible();
  });

  test('Shift+Tab from the trigger leaves and closes the menu', async ({ page }) => {
    const select = await openMenu(page);
    await select.locator('.select-trigger').focus();
    await page.keyboard.press('Shift+Tab');
    await expect(select.locator('.select-dropdown')).toHaveCount(0);
  });

  test('returns focus after selecting from menu search', async ({ page }) => {
    const select = await openMenu(page);
    await select.locator('.select-menu-search').focus();
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('Enter');
    await expect(select.locator('.select-trigger')).toBeFocused();
  });

  test('portaled menu supports forward and reverse Tab and exit', async ({ page }) => {
    const trigger = page.getByTestId('select-menu-portal').locator('.select-trigger');
    const search = page.getByTestId('select-menu-portal-menu-search');
    await trigger.focus();
    await page.keyboard.press('Enter');
    await expect(search).toBeVisible();
    await page.keyboard.press('Tab');
    await expect(search).toBeFocused();
    await page.keyboard.press('Shift+Tab');
    await expect(trigger).toBeFocused();
    await page.keyboard.press('Tab');
    await page.keyboard.press('Tab');
    await expect(search).toHaveCount(0);
    await expect(page.getByTestId('select-menu-portal-next')).toBeFocused();
  });

  test('bottom actions are outside the listbox and keyboard reachable', async ({ page }) => {
    const select = page.getByTestId('select-menu-multi');
    await select.locator('.select-trigger').focus();
    await page.keyboard.press('Enter');
    await expect(select.locator('.select-menu-search')).toBeVisible();
    await expect(select.locator('[role="listbox"] button')).toHaveCount(0);
    await page.keyboard.press('Tab');
    await expect(select.locator('.select-menu-search')).toBeFocused();
    await page.keyboard.press('Tab');
    await expect(page.getByTestId('select-menu-clear-all')).toBeFocused();
    await page.keyboard.press('Tab');
    await expect(page.getByTestId('select-menu-apply')).toBeFocused();
  });

  test('filtered select-all preserves other values and pinned actions apply or clear', async ({
    page
  }) => {
    const select = page.getByTestId('select-menu-multi');
    await select.locator('.select-trigger').click();
    await select.locator('.select-menu-search').fill('lon');
    await page.getByTestId('select-menu-multi-select-all').click();
    await expect(page.getByTestId('select-menu-apply')).toHaveText('Select (2)');
    await page.getByTestId('select-menu-apply').click();
    await expect(page.getByTestId('select-menu-applied')).toHaveText('Applied: nyc,ldn');
    await select.locator('.select-trigger').click();
    await expect(select.locator('.select-menu-search')).toHaveValue('');
    await page.getByTestId('select-menu-clear-all').click();
    await expect(page.getByTestId('select-menu-apply')).toHaveText('Select (0)');
  });

  test('recovers from no results and resets query on reopen', async ({ page }) => {
    const select = await openMenu(page);
    await select.locator('.select-menu-search').fill('not-a-city');
    await expect(select.locator('.select-empty')).toHaveText('No results');
    await select.locator('.select-menu-search').fill('Tokyo');
    await expect(select.locator('.select-option')).toHaveText('Tokyo');
    await page.keyboard.press('Escape');
    await select.locator('.select-trigger').click();
    await expect(select.locator('.select-option')).toHaveCount(8);
  });

  test('a default searchable Select still puts the input in the trigger', async ({ page }) => {
    // Back-compat: passes before the change and must keep passing.
    const select = page.getByTestId('select-search-demo');
    await expect(select.locator('.select-trigger .select-search')).toHaveCount(1);
  });
});
